  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const updateInput =
    input.assigneeId !== undefined && input.assigneeId !== before.assigneeId
      ? {
          ...input,
          assigneeId:
            input.assigneeId === null
              ? null
              : await resolveAssignmentTarget(
                  input.orgId,
                  input.assigneeId,
                  actor.userId,
                ),
        }
      : input;
  const after = await issueRepo.updateIssue(updateInput);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  if (
    updateInput.assigneeId !== undefined &&
    updateInput.assigneeId !== before.assigneeId &&
    after.assigneeId !== null
  ) {
    await emit("issue.assigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId: before.assigneeId,
      assigneeId: after.assigneeId,
    });
  }

  return after;
}

