export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const db = getDb();
  const row = db.transaction((tx) => {
    const archived = tx
      .update(members)
      .set({ ...archivePatch(), status: "suspended" })
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning()
      .get();

    if (archived) {
      tx.delete(memberAbsences)
        .where(
          and(
            orgPredicate(memberAbsences.orgId, orgId),
            eq(memberAbsences.userId, archived.userId),
          ),
        )
        .run();
      tx.update(memberAbsences)
        .set({ delegateUserId: null })
        .where(
          and(
            orgPredicate(memberAbsences.orgId, orgId),
            eq(memberAbsences.delegateUserId, archived.userId),
          ),
        )
        .run();
    }

    return archived;
  });

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

